    public static string DisplayName =>
        GeneratedDisplayNames.Resolve("Amount", null);
}

/// <summary>Value object for the code column</summary>
public sealed partial class CodeValue
    : ValueObjectStringBase<CodeValue>,
        IValueObject<CodeValue, string>
{
    private CodeValue(string value)
        : base(value) { }

    /// <summary>Creates the instance from an already-validated value (the public factories live in the base class; see <see cref="ValueObjectBaseCore{TSelf, TValue}.Create"/>).</summary>
    static CodeValue IValueObject<CodeValue, string>.New(string value) =>
        new(value);

    /// <summary>Auto-generated validation rules plus the user extension (OnValidate), called by the base class's Create / TryCreate / Validate.</summary>
    /// <remarks>An unimplemented OnValidate partial method takes its call away entirely, and an implemented one receives the error list by reference and possibly unallocated - so a value that passes every rule allocates nothing either way.</remarks>
